"use strict";(globalThis.webpackChunktemp_book=globalThis.webpackChunktemp_book||[]).push([[304],{7915:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"category","label":"Part 1: Foundations of Physical AI","items":[{"type":"link","href":"/GIAIC-Hackathon/docs/introduction","label":"Introduction","docId":"introduction","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/chapter1","label":"Chapter 1: Introduction to Physical AI","docId":"chapter1","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/chapter2","label":"Chapter 2: A Brief History of Robotics and AI","docId":"chapter2","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/physical-ai-course/module-1-ros2","label":"Chapter 3: The Robotic Nervous System (ROS 2)","docId":"physical-ai-course/module-1-ros2","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/chapter4","label":"Chapter 4: Simulating the World: Digital Twins and Physics Engines","docId":"chapter4","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/chapter5","label":"Chapter 5: Sensing the World: Computer Vision and Sensor Fusion","docId":"chapter5","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/chapter6","label":"Chapter 6: Acting in the World: Actuators and Control Systems","docId":"chapter6","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Part 2: Building Humanoid Robots","items":[{"type":"link","href":"/GIAIC-Hackathon/docs/chapter7","label":"Chapter 7: Humanoid Robot Design and Kinematics","docId":"chapter7","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/chapter8","label":"Chapter 8: Bipedal Locomotion and Gait Control","docId":"chapter8","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/chapter9","label":"Chapter 9: Manipulation and Grasping","docId":"chapter9","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/chapter10","label":"Chapter 10: Human-Robot Interaction and Social Robotics","docId":"chapter10","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Part 3: The AI Brain of the Robot","items":[{"type":"link","href":"/GIAIC-Hackathon/docs/chapter11","label":"Chapter 11: Introduction to Reinforcement Learning for Robotics","docId":"chapter11","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/chapter12","label":"Chapter 12: Learning from Demonstration: Imitation Learning","docId":"chapter12","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/chapter13","label":"Chapter 13: Vision-Language Models (VLMs) for Robotic Control","docId":"chapter13","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/physical-ai-course/module-3-nvidia-isaac","label":"Chapter 14: NVIDIA Isaac: A Platform for AI Robotics","docId":"physical-ai-course/module-3-nvidia-isaac","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/chapter15","label":"Chapter 15: Integrating Large Language Models (LLMs) with Robotics","docId":"chapter15","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Part 4: Advanced Topics and Future Directions","items":[{"type":"link","href":"/GIAIC-Hackathon/docs/chapter16","label":"Chapter 16: Swarm Robotics and Multi-Agent Systems","docId":"chapter16","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/chapter17","label":"Chapter 17: Soft Robotics and Bio-inspired Design","docId":"chapter17","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/chapter18","label":"Chapter 18: The Future of Humanoid Robotics","docId":"chapter18","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/chapter19","label":"Chapter 19: Ethical Considerations in Physical AI","docId":"chapter19","unlisted":false},{"type":"link","href":"/GIAIC-Hackathon/docs/chapter20","label":"Chapter 20: Getting Started with Your Own Robotics Project","docId":"chapter20","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"chapter1":{"id":"chapter1","title":"Chapter 1: Introduction to Physical AI","description":"Welcome to the foundational chapter of our journey into Physical AI and Humanoid Robotics. This chapter sets the stage for our exploration by defining what Physical AI is, why it matters, and what key components make it possible.","sidebar":"tutorialSidebar"},"chapter10":{"id":"chapter10","title":"Chapter 10: Human-Robot Interaction and Social Robotics","description":"As robots become more integrated into our daily lives, their ability to interact effectively and naturally with humans becomes paramount. Human-Robot Interaction (HRI) is the study of how humans and robots can communicate and collaborate. Social Robotics is a subfield of HRI focused on robots designed to interact with humans in a socially acceptable and meaningful way.","sidebar":"tutorialSidebar"},"chapter11":{"id":"chapter11","title":"Chapter 11: Introduction to Reinforcement Learning for Robotics","description":"Up to this point, we\'ve discussed how robots perceive and act based on pre-programmed instructions or explicit models. However, for robots to achieve true autonomy and adapt to unknown environments, they need to learn. Reinforcement Learning (RL) is a powerful paradigm within Artificial Intelligence that allows an agent to learn optimal behaviors through trial and error, by interacting with an environment. This chapter introduces the core concepts of RL and its application to robotics.","sidebar":"tutorialSidebar"},"chapter12":{"id":"chapter12","title":"Chapter 12: Learning from Demonstration: Imitation Learning","description":"Reinforcement Learning, as we saw in the previous chapter, is incredibly powerful but often suffers from sample inefficiency\u2014it requires a vast number of trials to learn complex behaviors. This is particularly problematic for robots in the real world. Imitation Learning (IL) offers a compelling alternative or complement, allowing robots to learn directly from observing human demonstrations. Instead of trial and error, the robot learns \\"how to\\" by mimicking an expert.","sidebar":"tutorialSidebar"},"chapter13":{"id":"chapter13","title":"Chapter 13: Vision-Language Models (VLMs) for Robotic Control","description":"The recent advancements in large language models (LLMs) have revolutionized our ability to interact with AI using natural language. When these powerful language capabilities are combined with advanced computer vision, we get Vision-Language Models (VLMs). VLMs are rapidly becoming a cornerstone for intuitive robotic control, allowing robots to understand high-level human instructions and perceive their environment with a nuanced, semantic understanding.","sidebar":"tutorialSidebar"},"chapter15":{"id":"chapter15","title":"Chapter 15: Integrating Large Language Models (LLMs) with Robotics","description":"The advent of Large Language Models (LLMs) has marked a pivotal moment in AI, showcasing an unprecedented ability to understand, generate, and reason with human language. While initially focused on text-based tasks, their integration into robotics is opening up new frontiers, allowing robots to interpret complex instructions, engage in high-level reasoning, and even plan multi-step tasks based on natural language input. This chapter explores how LLMs are being integrated with robotic systems and the profound implications for physical AI.","sidebar":"tutorialSidebar"},"chapter16":{"id":"chapter16","title":"Chapter 16: Swarm Robotics and Multi-Agent Systems","description":"While individual robots, especially humanoids, offer impressive capabilities, many real-world problems benefit from the coordinated efforts of multiple robots working together. Swarm Robotics and Multi-Agent Systems explore how groups of robots can achieve tasks that are difficult or impossible for a single robot, inspired by collective intelligence observed in nature.","sidebar":"tutorialSidebar"},"chapter17":{"id":"chapter17","title":"Chapter 17: Soft Robotics and Bio-inspired Design","description":"Traditional robots are typically rigid, made from stiff materials like metal and hard plastics, and actuated by motors and gears. While powerful and precise, this rigidity can limit their adaptability, safety in human interaction, and ability to navigate complex, unstructured environments. Soft robotics offers a revolutionary paradigm shift, drawing inspiration from biology to create robots made from compliant, deformable materials that are inherently safer, more adaptable, and capable of novel forms of movement.","sidebar":"tutorialSidebar"},"chapter18":{"id":"chapter18","title":"Chapter 18: The Future of Humanoid Robotics","description":"We have journeyed through the foundational principles, design challenges, and cutting-edge AI techniques that define Physical AI and humanoid robotics today. This chapter casts our gaze forward, exploring the near and distant future of this transformative field, considering technological advancements, societal impact, and the grand challenges that still lie ahead.","sidebar":"tutorialSidebar"},"chapter19":{"id":"chapter19","title":"Chapter 19: Ethical Considerations in Physical AI","description":"As we develop increasingly autonomous and intelligent physical AI systems, particularly humanoids, it becomes imperative to confront the profound ethical implications they raise. This chapter explores the critical moral questions and societal challenges that arise when robots move beyond tools and begin to occupy roles of increasing agency and interaction in our world.","sidebar":"tutorialSidebar"},"chapter2":{"id":"chapter2","title":"Chapter 2: A Brief History of Robotics and AI","description":"To understand where we are going, it\'s essential to know where we\'ve come from. The fields of robotics and artificial intelligence have a rich and intertwined history, marked by visionary thinkers, key breakthroughs, and periods of both excitement and disillusionment.","sidebar":"tutorialSidebar"},"chapter20":{"id":"chapter20","title":"Chapter 20: Getting Started with Your Own Robotics Project","description":"Congratulations on making it to the final chapter of \\"Physical AI and Humanoid Robotics\\"! You\'ve gained a comprehensive understanding of the foundational concepts, cutting-edge technologies, and ethical considerations in this exciting field. Now, it\'s time to translate that knowledge into hands-on experience. This chapter provides guidance and resources to help you embark on your own robotics journey, from simple projects to more ambitious endeavors.","sidebar":"tutorialSidebar"},"chapter4":{"id":"chapter4","title":"Chapter 4: Simulating the World: Digital Twins and Physics Engines","description":"Before a robot ever takes its first step in the real world, it takes thousands of steps in a virtual one. Simulation is one of the most critical tools in modern robotics, allowing for rapid development, testing, and training of AI systems in a safe, controlled, and cost-effective manner.","sidebar":"tutorialSidebar"},"chapter5":{"id":"chapter5","title":"Chapter 5: Sensing the World: Computer Vision and Sensor Fusion","description":"A robot\'s ability to act intelligently is fundamentally limited by its ability to perceive its environment accurately. Just as humans rely on their senses, robots rely on a suite of sensors to gather information about the world. This chapter covers the primary sensors used in modern robotics, with a focus on computer vision and the critical process of sensor fusion.","sidebar":"tutorialSidebar"},"chapter6":{"id":"chapter6","title":"Chapter 6: Acting in the World: Actuators and Control Systems","description":"Perception allows a robot to understand its environment, but it\'s the actuators and control systems that enable it to interact with the physical world. This chapter delves into the mechanisms that translate electrical signals into physical motion and the intelligent systems that orchestrate these movements to achieve desired tasks.","sidebar":"tutorialSidebar"},"chapter7":{"id":"chapter7","title":"Chapter 7: Humanoid Robot Design and Kinematics","description":"Humanoid robots are machines designed to mimic the human body\'s form and function, enabling them to operate in environments built for people. This chapter explores the fundamental design principles behind these complex machines and introduces the essential mathematical tools of kinematics that allow us to understand and control their movements.","sidebar":"tutorialSidebar"},"chapter8":{"id":"chapter8","title":"Chapter 8: Bipedal Locomotion and Gait Control","description":"One of the most distinguishing and challenging features of humanoid robots is their ability to walk on two legs \u2013 bipedal locomotion. This chapter delves into the complexities of achieving stable and efficient gait control, a task that humans perform effortlessly but that pushes the boundaries of robotic engineering.","sidebar":"tutorialSidebar"},"chapter9":{"id":"chapter9","title":"Chapter 9: Manipulation and Grasping","description":"After mastering locomotion, the next critical ability for a humanoid robot is to interact with its environment by manipulating objects. Manipulation involves using the robot\'s arms and hands to perform tasks like picking up, placing, assembling, or operating tools. Grasping is a fundamental sub-problem within manipulation, focusing specifically on how a robot can securely hold an object.","sidebar":"tutorialSidebar"},"introduction":{"id":"introduction","title":"Introduction","description":"Welcome to \\"Physical AI and Humanoid Robotics\\"!","sidebar":"tutorialSidebar"},"physical-ai-course/module-1-ros2":{"id":"physical-ai-course/module-1-ros2","title":"Chapter 3: The Robotic Nervous System (ROS 2)","description":"Just as a biological organism relies on a nervous system to coordinate sensory input and motor output, a robot needs a robust communication layer to connect its various components. In modern robotics, that role is filled by middleware, and the de facto standard is the Robot Operating System (ROS).","sidebar":"tutorialSidebar"},"physical-ai-course/module-2-digital-twin":{"id":"physical-ai-course/module-2-digital-twin","title":"Module 2: The Digital Twin (Gazebo & Unity)","description":"Focus: Physics simulation and environment building."},"physical-ai-course/module-3-nvidia-isaac":{"id":"physical-ai-course/module-3-nvidia-isaac","title":"Chapter 14: NVIDIA Isaac: A Platform for AI Robotics","description":"The development of advanced physical AI and humanoid robotics demands powerful tools that bridge the gap between simulation and the real world, accelerate AI training, and provide robust frameworks for deployment. NVIDIA Isaac is a comprehensive platform designed to meet these needs, offering a suite of software and hardware solutions for building, training, and deploying AI-powered robots.","sidebar":"tutorialSidebar"},"physical-ai-course/module-4-vla":{"id":"physical-ai-course/module-4-vla","title":"Module 4: Vision-Language-Action (VLA)","description":"Focus: The convergence of LLMs and Robotics."}}}}')}}]);